tool_input.command:
$deadline = (Get-Date).AddSeconds(120)
$up = $false
while ((Get-Date) -lt $deadline) {
    $listener = Get-NetTCPConnection -LocalPort 1933 -ErrorAction SilentlyContinue | Where-Object { $_.State -eq 'Listen' }
    if ($listener) { $up = $true; break }
    Start-Sleep -Seconds 3
}
if ($up) {
    $pid1933 = (Get-NetTCPConnection -LocalPort 1933 -ErrorAction SilentlyContinue | Where-Object { $_.State -eq 'Listen' }).OwningProcess
    Write-Host "OpenViking is LISTENING on 1933 (pid $pid1933)"
} else {
    Write-Host "OpenViking NOT up after 120s"
}
# show running openviking processes
Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match 'openviking-server' } | Select-Object ProcessId, Name | Format-Table -AutoSize | Out-String -Width 200
